export function InputSizes() {
  const sizes = [
    { label: 'Small', size: 'sm' as const },
    { label: 'Default', size: 'default' as const },
    { label: 'Large', size: 'lg' as const },
  ];

  return (
    <div className="space-y-6">
      {sizes.map(({ size }) => {
        const { description, gap } = inputFieldConfig[size];

        return (
          <div key={size} className="flex gap-6">
            <FieldSet className={`${FIELD_WIDTH} ${gap}`}>
              <FieldLabel
                htmlFor={`input-size-${size}`}
                className={getInputLabelClass(size)}>
                Label
              </FieldLabel>
              <Input
                id={`input-size-${size}`}
                size={size}
                placeholder="Placeholder"
              />
              <FieldDescription className={description}>
                Helper text
              </FieldDescription>
            </FieldSet>

            <FieldSet className={`${FIELD_WIDTH} ${gap}`}>
              <FieldLabel
                htmlFor={`input-size-${size}-inline`}
                className={getInputLabelClass(size, 'inline')}>
                Label
              </FieldLabel>
              <Input
                id={`input-size-${size}-inline`}
                size={size}
                variant="inline"
                placeholder="Placeholder"
              />
              <FieldDescription className={description}>
                Helper text
              </FieldDescription>
            </FieldSet>
          </div>
        );
      })}
    </div>
  );
}

export function InputStates() {
  const { description: descriptionClass, gap } = inputFieldConfig.default;

  const states = [
    {
      label: 'With Value',
      props: { defaultValue: 'Some text value' },
      inlineProps: { defaultValue: 'Some text value' },
    },
    {
      label: 'Disabled',
      props: { disabled: true, placeholder: 'Placeholder' },
      inlineProps: { disabled: true, placeholder: 'Placeholder' },
    },
    {
      label: 'Error',
      props: { 'aria-invalid': true, placeholder: 'Placeholder' } as const,
      inlineProps: {
        'aria-invalid': true,
        placeholder: 'Placeholder',
      } as const,
      statusDescriptionClass: 'text-status-error',
      descriptionText: 'Feedback message here',
    },
    {
      label: 'Warning',
      props: {
        className: '!border-status-warning',
        placeholder: 'Placeholder',
      },
      inlineProps: {
        className: '!border-b-status-warning',
        placeholder: 'Placeholder',
      },
      statusDescriptionClass: 'text-status-warning',
      descriptionText: 'Feedback message here',
    },
    {
      label: 'Success',
      props: {
        className: '!border-status-success',
        placeholder: 'Placeholder',
      },
      inlineProps: {
        className: '!border-b-status-success',
        placeholder: 'Placeholder',
      },
      statusDescriptionClass: 'text-status-success',
      descriptionText: 'Feedback message here',
    },
  ];

  return (
    <div className="space-y-6">
      {states.map(
        ({
          label,
          props,
          inlineProps,
          statusDescriptionClass,
          descriptionText,
        }) => {
          const stateIdBase = `input-state-${label.toLowerCase().replaceAll(' ', '-')}`;

          return (
            <div key={label} className="flex gap-6">
              <FieldSet className={`${FIELD_WIDTH} ${gap}`}>
                <FieldLabel
                  htmlFor={stateIdBase}
                  className={getInputLabelClass('default')}>
                  Label
                </FieldLabel>
                <Input id={stateIdBase} {...props} />
                <FieldDescription
                  className={`${descriptionClass} ${statusDescriptionClass ?? ''}`}>
                  {descriptionText ?? 'Helper text'}
                </FieldDescription>
              </FieldSet>

              <FieldSet className={`${FIELD_WIDTH} ${gap}`}>
                <FieldLabel
                  htmlFor={`${stateIdBase}-inline`}
                  className={getInputLabelClass('default', 'inline')}>
                  Label
                </FieldLabel>
                <Input
                  id={`${stateIdBase}-inline`}
                  variant="inline"
                  {...inlineProps}
                />
                <FieldDescription
                  className={`${descriptionClass} ${statusDescriptionClass ?? ''}`}>
                  {descriptionText ?? 'Helper text'}
                </FieldDescription>
              </FieldSet>
            </div>
          );
        },
      )}
    </div>
  );
}

